"use client";

import React from "react";

export default function Example() {
	return (
		<div className="h-screen w-full flex items-center justify-center relative overflow-hidden bg-black">
			coming soon
		</div>
	);
}

"use client";

import React, { ReactNode, useState } from "react";

import Link from "next/link";
import { usePathname } from "next/navigation";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import {
	AnimatePresence,
	motion,
	useMotionValueEvent,
	useScroll,
} from "framer-motion";
import { IoIosClose, IoIosMenu } from "react-icons/io";

import { ModeToggle } from "./atoms/mode-toggle";

type Props = {
	navItems: {
		link: string;
		title: string;
		target?: "_blank";
	}[];
};

const DesktopNavbar = ({ navItems }: Props) => {
	const { scrollY } = useScroll();

	const [showBackground, setShowBackground] = useState(false);

	useMotionValueEvent(scrollY, "change", (value) => {
		if (value > 100) {
			setShowBackground(true);
		} else {
			setShowBackground(false);
		}
	});
	return (
		<motion.div
			className={cn(
				"w-full flex relative justify-between px-4 py-3 rounded-md  transition duration-200 bg-transparent mx-auto"
			)}
			animate={{
				width: showBackground ? "80%" : "100%",
				background: showBackground ? "var(--neutral-900)" : "transparent",
			}}
			transition={{
				duration: 0.4,
			}}
		>
			<AnimatePresence>
				{showBackground && (
					<motion.div
						key={String(showBackground)}
						initial={{ opacity: 0 }}
						animate={{ opacity: 1 }}
						transition={{
							duration: 1,
						}}
						className="absolute inset-0 h-full w-full bg-neutral-900 pointer-events-none [mask-image:linear-gradient(to_bottom,white,transparent,white)] rounded-full"
					/>
				)}
			</AnimatePresence>
			<div className="flex flex-row gap-2 items-center">
				{/* <Logo /> */}
				<div className="flex items-center gap-1.5">
					{navItems.map((item) => (
						<NavBarItem
							href={item.link}
							key={item.title}
							target={item.target}
						>
							{item.title}
						</NavBarItem>
					))}
				</div>
			</div>
			<div className="flex space-x-2 items-center">
				<Button as={Link} href="/register">
					Register
				</Button>
				<Button>Book a demo</Button>
				<ModeToggle />
			</div>
		</motion.div>
	);
};

const navItems = [
	{
		title: "Features",
		link: "/features",
	},
	{
		title: "Pricing",
		link: "/pricing",
	},

	{
		title: "Blog",
		link: "/blog",
	},
	{
		title: "Contact",
		link: "/contact",
	},
];

function ResizeNavBar() {
	return (
		<motion.nav
			initial={{
				y: -80,
			}}
			animate={{
				y: 0,
			}}
			transition={{
				ease: [0.6, 0.05, 0.1, 0.9],
				duration: 0.8,
			}}
			className="max-w-7xl  fixed top-4  mx-auto inset-x-0 z-50 w-[95%] lg:w-full"
		>
			<div className="hidden lg:block w-full">
				<DesktopNavbar navItems={navItems} />
			</div>
			<div className="flex h-full w-full items-center lg:hidden ">
				<MobileNavbar navItems={navItems} />
			</div>
		</motion.nav>
	);
}

const MobileNavbar = ({ navItems }: any) => {
	const [open, setOpen] = useState(false);

	const { scrollY } = useScroll();

	const [showBackground, setShowBackground] = useState(false);

	useMotionValueEvent(scrollY, "change", (value) => {
		if (value > 100) {
			setShowBackground(true);
		} else {
			setShowBackground(false);
		}
	});

	return (
		<div
			className={cn(
				"flex justify-between bg-transparent items-center w-full rounded-md px-2.5 py-1.5 transition duration-200",
				showBackground &&
					" bg-neutral-900  shadow-[0px_-2px_0px_0px_var(--neutral-800),0px_2px_0px_0px_var(--neutral-800)]"
			)}
		>
			{/* <Logo /> */}
			<IoIosMenu
				className="text-white h-6 w-6"
				onClick={() => setOpen(!open)}
			/>
			{open && (
				<div className="fixed inset-0 bg-black z-50 flex flex-col items-start justify-start space-y-10  pt-5  text-xl text-zinc-600  transition duration-200 hover:text-zinc-800">
					<div className="flex items-center justify-between w-full px-5">
						{/* <Logo /> */}
						<div className="flex items-center space-x-2">
							<IoIosClose
								className="h-8 w-8 text-white"
								onClick={() => setOpen(!open)}
							/>
						</div>
					</div>
					<div className="flex flex-col items-start justify-start gap-[14px] px-8">
						{navItems.map((navItem: any, idx: number) => (
							<>
								{navItem.children && navItem.children.length > 0 ? (
									<>
										{navItem.children.map(
											(childNavItem: any, idx: number) => (
												<Link
													key={`link=${idx}`}
													href={childNavItem.link}
													onClick={() => setOpen(false)}
													className="relative max-w-[15rem] text-left text-2xl"
												>
													<span className="block text-white">
														{childNavItem.title}
													</span>
												</Link>
											)
										)}
									</>
								) : (
									<Link
										key={`link=${idx}`}
										href={navItem.link}
										onClick={() => setOpen(false)}
										className="relative"
									>
										<span className="block text-[26px] text-white">
											{navItem.title}
										</span>
									</Link>
								)}
							</>
						))}
					</div>
					<div className="flex flex-row w-full items-start gap-2.5  px-8 py-4 ">
						<Button>Book a demo</Button>
						<Button
							variant="simple"
							as={Link}
							href="/register"
							onClick={() => {
								setOpen(false);
							}}
						>
							Register
						</Button>
						<ModeToggle />
					</div>
				</div>
			)}
		</div>
	);
};

type NavBarItemProps = {
	href: string;
	children: ReactNode;
	active?: boolean;
	className?: string;
	target?: "_blank";
};

export function NavBarItem({
	children,
	href,
	active,
	target,
	className,
}: NavBarItemProps) {
	const pathname = usePathname();

	return (
		<Link
			href={href}
			className={cn(
				"flex items-center justify-center  text-sm leading-[110%] px-4 py-2 rounded-md text-white  hover:bg-neutral-800 hover:text-white/80 dark:text-white hover:shadow-[0px_1px_0px_0px_#FFFFFF20_inset] transition duration-200",
				(active || pathname?.includes(href)) &&
					"bg-transparent dark:text-white",
				className
			)}
			target={target}
		>
			{children}
		</Link>
	);
}

export default ResizeNavBar;

import * as React from "react";

import { cn } from "@/lib/utils";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";

const buttonVariants = cva(
	"inline-flex items-center justify-center whitespace-nowrap rounded-md text-sm text-white hover:text-gray-400 font-medium ring-offset-background transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50",
	{
		variants: {
			variant: {
				simple:
					"bg-secondary relative z-10 bg-transparent hover:border-secondary hover:bg-secondary/50  border border-transparent dark:text-white text-sm md:text-sm transition font-medium duration-200  rounded-md px-4 py-2  flex items-center justify-center",
				default: "bg-primary text-primary-foreground hover:bg-primary/90",
				destructive:
					"bg-destructive text-destructive-foreground hover:bg-destructive/90",
				outline:
					"border border-input bg-background hover:bg-accent hover:text-accent-foreground",
				secondary:
					"bg-secondary text-secondary-foreground hover:bg-secondary/80",
				ghost: "hover:bg-accent hover:text-black hover:stroke-black dark:text-white text-black",
				link: "text-primary underline-offset-4 hover:underline",
			},
			size: {
				default: "h-10 px-4 py-2",
				sm: "h-9 rounded-md px-3",
				lg: "h-11 rounded-md px-8",
				icon: "h-10 w-10",
			},
		},
		defaultVariants: {
			variant: "default",
			size: "default",
		},
	}
);

export interface ButtonProps
	extends React.ButtonHTMLAttributes<HTMLButtonElement>,
		VariantProps<typeof buttonVariants> {
	asChild?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
	({ className, variant, size, asChild = false, ...props }, ref) => {
		const Comp = asChild ? Slot : "button";
		return (
			<Comp
				className={cn(buttonVariants({ variant, size, className }))}
				ref={ref}
				{...props}
			/>
		);
	}
);
Button.displayName = "Button";

export { Button, buttonVariants };

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
